def arr(name, typ, vals, w):
    rows = []
    for i in range(0, len(vals), 16):
        rows.append("        " + ", ".join('"' + format(v & ((1 << w) - 1), "0" + str(w) + "b") + '"' for v in vals[i:i + 16]))
    return "    constant " + name + " : " + typ + " := (\n" + ",\n".join(rows) + "\n    );"


def emit():
    cs = [arr("C_GE", "t_ge", GE, 12), arr("C_GO", "t_go", GO, 12), arr("C_HH", "t_hh", HH, 12),
          arr("C_RING", "t_ring", RING, 8), arr("C_CT", "t_ct", CT, 32)]
    txt = ("-- argyle_pkg.vhd -- GENERATED by argyle.py; edit the generator, not this file.\n"
           "-- C_GE / C_GO: horizontal oscillator (even / odd part).  C_HH: vertical oscillator.\n"
           "-- C_RING: ring waveform over the field.  C_CT: colour table over (H, shifted G).\n\n"
           "library ieee;\nuse ieee.std_logic_1164.all;\n\npackage argyle_pkg is\n"
           "    type t_ge is array(0 to 511) of std_logic_vector(11 downto 0);\n"
           "    type t_go is array(0 to 255) of std_logic_vector(11 downto 0);\n"
           "    type t_hh is array(0 to 255) of std_logic_vector(11 downto 0);\n"
           "    type t_ring is array(0 to 511) of std_logic_vector(7 downto 0);\n"
           "    type t_ct is array(0 to 1023) of std_logic_vector(31 downto 0);\n" +
           "\n".join(cs) + "\nend package argyle_pkg;\n")
    with open(os.path.join(HERE, "argyle_pkg.vhd"), "w") as fh:
        fh.write(txt)


if __name__ == "__main__":
    emit()
